#ifdef CONFIG_SPI_FLASH_FATFS

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#ifndef CONFIG_BES_SPI_FLASH_CSNUM
#  define CONFIG_BES_SPI_FLASH_CSNUM 0
#endif

