/* BES I2C bus initialization function from libbeschip_ap.a */

extern struct i2c_master_s *bes_i2cbus_initialize(int port);

#ifdef CONFIG_MPU6500_I2C

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#ifndef CONFIG_MPU6500_I2C_PORT
#  define CONFIG_MPU6500_I2C_PORT 0
#endif

#ifndef CONFIG_MPU6500_I2C_ADDR
#  define CONFIG_MPU6500_I2C_ADDR 0x68
#endif

#ifndef CONFIG_MPU6500_DEVNAME
#  define CONFIG_MPU6500_DEVNAME "/dev/accel0"
#endif

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: bes_mpu6500_initialize
 *
 * Description:
 *   Initialize and register the MPU6500 I2C IMU driver.
 *   Uses I2C0 for MPU6500 connection.
 *
 *   MPU6500 I2C Address: 0x68 (AD0=GND) or 0x69 (AD0=VCC)
 *   Wiring:
 *     SCL -> G36 (I2C0_SCL)
 *     SDA -> G37 (I2C0_SDA)
 *     AD0 -> GND (address 0x68)
 *     INT -> G40 (optional, for interrupt mode)
 *
 ****************************************************************************/

int bes_mpu6500_initialize(void)
{
  struct i2c_master_s *i2c;
  struct mpu_config_s config;
  static bool initialized = false;
  int ret;

  /* Have we already initialized? */

  if (!initialized)
    {
      /* No.. Get the I2C port driver */

      i2c = bes_i2cbus_initialize(CONFIG_MPU6500_I2C_PORT);
      if (!i2c)
        {
          syslog(LOG_ERR, "ERROR: Failed to initialize I2C port %d\n",
                 CONFIG_MPU6500_I2C_PORT);
          return -ENODEV;
        }

      /* Configure the MPU6500 */

      memset(&config, 0, sizeof(config));
      config.i2c = i2c;
      config.addr = CONFIG_MPU6500_I2C_ADDR;

      /* Register the MPU60x0 driver (compatible with MPU6500) */

      ret = mpu60x0_register(CONFIG_MPU6500_DEVNAME, &config);
      if (ret < 0)
        {
          syslog(LOG_ERR, "ERROR: Failed to register MPU6500 driver: %d\n",
                 ret);
          return ret;
        }

      syslog(LOG_INFO, "INFO: MPU6500 IMU registered at %s (I2C%d addr 0x%02x)\n",
             CONFIG_MPU6500_DEVNAME, CONFIG_MPU6500_I2C_PORT,
             CONFIG_MPU6500_I2C_ADDR);

      /* Now we are initialized */

      initialized = true;
    }

  return OK;
}

#endif /* CONFIG_MPU6500_I2C */

