#include <nuttx/config.h>

#include <stdbool.h>
#include <stdio.h>
#include <errno.h>
#include <debug.h>

#include <nuttx/spi/spi.h>
#include <nuttx/mtd/mtd.h>
#include <nuttx/fs/fs.h>
#include <syslog.h>

/* BES SPI bus initialization function from libbeschip_ap.a */

extern struct spi_dev_s *bes_spibus_initialize(int port);

#ifdef CONFIG_W25Q64_SPI

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#ifndef CONFIG_W25Q64_SPI_PORT
#  define CONFIG_W25Q64_SPI_PORT 0
#endif

#ifndef CONFIG_W25Q64_MOUNTPOINT
#  define CONFIG_W25Q64_MOUNTPOINT "/mnt/w25q64"
#endif

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: bes_w25q64_initialize
 *
 * Description:
 *   Initialize and mount the W25Q64 SPI Flash with FAT file system.
 *   The FLASH will be mounted at CONFIG_W25Q64_MOUNTPOINT.
 *
 *   W25Q64 Wiring:
 *     SLK (CLK) -> G32 (SPI0_CLK)
 *     CS        -> G33 (SPI0_CS0)
 *     D0 (DO)   -> G34 (SPI0_DI0, MISO)
 *     D1 (DI)   -> G35 (SPI0_DIO, MOSI)
 *     VCC       -> 3.3V
 *     GND       -> GND
 *
 ****************************************************************************/

int bes_w25q64_initialize(void)
{
  struct spi_dev_s *spi;
  struct mtd_dev_s *mtd;
  static bool initialized = false;
  int ret;

  /* Have we already initialized? */

  if (!initialized)
    {
      /* No.. Get the SPI port driver */

      spi = bes_spibus_initialize(CONFIG_W25Q64_SPI_PORT);
      if (!spi)
        {
          syslog(LOG_ERR, "ERROR: Failed to initialize SPI port %d\n",
                 CONFIG_W25Q64_SPI_PORT);
          return -ENODEV;
        }

      /* Now bind the SPI interface to the W25 FLASH driver */

      mtd = w25_initialize(spi);
      if (!mtd)
        {
          syslog(LOG_ERR, "ERROR: Failed to bind SPI port to W25Q64 driver\n");
          return -ENODEV;
        }

      /* Use the FTL layer to wrap the MTD driver as a block driver
       * at /dev/mtdblockN, where N=minor device number.
       * Use 1 for minor to avoid conflict with SPI Flash (which uses 0).
       */

      ret = ftl_initialize(1, mtd);
      if (ret < 0)
        {
          syslog(LOG_ERR, "ERROR: Failed to initialize the FTL layer: %d\n",
                 ret);
          return ret;
        }

      /* Mount the FAT file system */

      ret = nx_mount("/dev/mtdblock1", CONFIG_W25Q64_MOUNTPOINT,
                     "vfat", 0, NULL);
      if (ret < 0)
        {
          syslog(LOG_WARNING, "WARNING: Failed to mount FAT at %s: %d\n"
                 "You may need to format it first: mkfatfs /dev/mtdblock1\n",
                 CONFIG_W25Q64_MOUNTPOINT, ret);
          /* Don't return error - flash is accessible as /dev/mtdblock1 */
        }
      else
        {
          syslog(LOG_INFO, "INFO: FAT volume %s mount W25Q64 success\n",
                 CONFIG_W25Q64_MOUNTPOINT);
        }

      syslog(LOG_INFO, "INFO: W25Q64 SPI Flash registered at /dev/mtdblock1 "
             "(SPI%d CS%d)\n", CONFIG_W25Q64_SPI_PORT, 0);

      /* Now we are initialized */

      initialized = true;
    }

  return OK;
}

#endif /* CONFIG_W25Q64_SPI */

