126	static int test_w25q64(void)
127	{
128	  int fd;
129	  int ret;
130	  char write_buf[] = "Hello W25Q64!";
131	  char read_buf[64];
132	  ssize_t bytes_written;
133	  ssize_t bytes_read;
134	
135	  printf("\n=== W25Q64 SPI Flash Test ===\n");
136	
137	  /* Check if device exists */
138	
139	  fd = open(SENSOR_TEST_W25Q64_DEV, O_RDWR);
140	  if (fd < 0)
141	    {
142	      printf("ERROR: Failed to open %s: %d\n",
143	             SENSOR_TEST_W25Q64_DEV, errno);
144	      return -errno;
145	    }
146	
147	  printf("SUCCESS: Opened %s\n", SENSOR_TEST_W25Q64_DEV);
148	
149	  /* Write test data */
150	
151	  bytes_written = write(fd, write_buf, strlen(write_buf));
152	  if (bytes_written < 0)
153	    {
154	      printf("WARNING: Failed to write: %d\n", errno);
155	    }
156	  else
157	    {
158	      printf("Written %zd bytes: \"%s\"\n", bytes_written, write_buf);
159	    }
160	
161	  /* Seek back to beginning */
162	
163	  lseek(fd, 0, SEEK_SET);
164	
165	  /* Read test data */
166	
167	  bytes_read = read(fd, read_buf, sizeof(read_buf) - 1);
168	  if (bytes_read < 0)
169	    {
170	      printf("WARNING: Failed to read: %d\n", errno);
171	    }
172	  else
173	    {
174	      read_buf[bytes_read] = '\0';
175	      printf("Read %zd bytes: \"%s\"\n", bytes_read, read_buf);
176	
177	      /* Verify data */
178	
179	      if (strcmp(write_buf, read_buf) == 0)
180	        {
181	          printf("SUCCESS: Data verification passed!\n");
182	        }
183	      else
184	        {
185	          printf("WARNING: Data mismatch!\n");
186	        }
187	    }
188	
189	  /* Close the device */
190	
191	  close(fd);
192	
193	  /* Check if mount point exists */
194	
195	  ret = access(SENSOR_TEST_MOUNT_POINT, F_OK);
196	  if (ret == 0)
