    {
      printf("WARNING: Failed to read gyroscope: %d\n", errno);
    }
  else
    {
      printf("Gyroscope (°/s):\n");
      printf("  X: %8.2f\n", gyro[0]);
      printf("  Y: %8.2f\n", gyro[1]);
      printf("  Z: %8.2f\n", gyro[2]);
    }

  /* Close the device */

  close(fd);
  printf("MPU6500 test completed.\n");

  return OK;
}
#endif /* CONFIG_MPU6500_I2C */

/****************************************************************************
 * Name: test_w25q64
 *
 * Description:
 *   Test W25Q64 SPI Flash by reading and writing data.
 *
 ****************************************************************************/

#ifdef CONFIG_W25Q64_SPI
static int test_w25q64(void)
{
  int fd;
  int ret;
  char write_buf[] = "Hello W25Q64!";
  char read_buf[64];
  ssize_t bytes_written;
  ssize_t bytes_read;

  printf("\n=== W25Q64 SPI Flash Test ===\n");

  /* Check if device exists */

  fd = open(SENSOR_TEST_W25Q64_DEV, O_RDWR);
  if (fd < 0)
    {
      printf("ERROR: Failed to open %s: %d\n",
             SENSOR_TEST_W25Q64_DEV, errno);
      return -errno;
    }

  printf("SUCCESS: Opened %s\n", SENSOR_TEST_W25Q64_DEV);

  /* Write test data */

  bytes_written = write(fd, write_buf, strlen(write_buf));
  if (bytes_written < 0)
    {
      printf("WARNING: Failed to write: %d\n", errno);
    }
  else
    {
      printf("Written %zd bytes: \"%s\"\n", bytes_written, write_buf);
    }

  /* Seek back to beginning */

  lseek(fd, 0, SEEK_SET);

  /* Read test data */

  bytes_read = read(fd, read_buf, sizeof(read_buf) - 1);
  if (bytes_read < 0)
    {
      printf("WARNING: Failed to read: %d\n", errno);
    }
  else
    {
      read_buf[bytes_read] = '\0';
      printf("Read %zd bytes: \"%s\"\n", bytes_read, read_buf);

      /* Verify data */

      if (strcmp(write_buf, read_buf) == 0)
        {
          printf("SUCCESS: Data verification passed!\n");
        }
      else
        {
          printf("WARNING: Data mismatch!\n");
        }
    }

  /* Close the device */

  close(fd);

  /* Check if mount point exists */

  ret = access(SENSOR_TEST_MOUNT_POINT, F_OK);
  if (ret == 0)
    {
      printf("SUCCESS: %s is mounted\n", SENSOR_TEST_MOUNT_POINT);
    }
  else
    {
      printf("INFO: %s is not mounted\n", SENSOR_TEST_MOUNT_POINT);
      printf("      You can format and mount it manually:\n");
      printf("      mkfatfs /dev/mtdblock1\n");
      printf("      mount -t vfat /dev/mtdblock1 /mnt/w25q64\n");
    }

  printf("W25Q64 test completed.\n");

  return OK;
}
#endif /* CONFIG_W25Q64_SPI */

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: sensor_test_main
 *
 * Description:
 *   Main entry point for the sensor test application.
 *
 ****************************************************************************/

int main(int argc, char *argv[])
{
  printf("=== BES2800BP Sensor Test ===\n");

#ifdef CONFIG_MPU6500_I2C
  test_mpu6500();
#else
  printf("\nMPU6500: Not enabled (CONFIG_MPU6500_I2C=n)\n");
#endif

#ifdef CONFIG_W25Q64_SPI
  test_w25q64();
#else
  printf("\nW25Q64: Not enabled (CONFIG_W25Q64_SPI=n)\n");
#endif

  printf("\n=== Test Complete ===\n");

  return OK;
}

