1	/****************************************************************************
2	 * apps/examples/elderly_bes/sensor_manager.c
3	 *
4	 * 传感器管理器：BMI270 数据采集、跌倒检测、步数统计、姿态识别。
5	 * 传感器未连接时使用模拟数据，确保应用可独立运行。
6	 ****************************************************************************/
7	
8	/****************************************************************************
9	 * Included Files
10	 ****************************************************************************/
11	
12	#include "sensor_manager.h"
13	#include <math.h>
14	#include <fcntl.h>
15	#include <unistd.h>
16	#include <time.h>
17	
18	/****************************************************************************
19	 * Pre-processor Definitions
20	 ****************************************************************************/
21	
22	/* 跌倒检测阈值 */
23	
24	#define FREEFALL_THRESH     3.0f    /* 自由落体: 合加速度 < 3 m/s² */
25	#define IMPACT_THRESH       25.0f   /* 撞击: 合加速度 > 25 m/s² */
26	#define FALL_TIME_WINDOW_MS 1500    /* 自由落体→撞击 时间窗口 (ms) */
27	#define FALL_CONFIRM_MS     2000    /* 跌倒确认后持续时间 (ms) */
28	#define FALL_COOLDOWN_MS    10000   /* 跌倒报警冷却时间 (ms) */
29	
30	/* 步数检测阈值 */
31	
32	#define STEP_ACCEL_THRESH   1.5f    /* 步行加速度变化阈值 (m/s²) */
33	#define STEP_MIN_INTERVAL   250     /* 最小步间隔 (ms) */
34	#define STEP_MAX_INTERVAL   2000    /* 最大步间隔 (ms) */
35	
36	/* 姿态检测阈值 (基于重力分量) */
37	
38	#define STANDING_Z_THRESH   7.0f    /* 站立: Z > 7 */
39	#define LYING_Z_THRESH      3.0f    /* 躺下: Z < 3 */
40	#define WALKING_GYRO_THRESH 30.0f   /* 行走: 角速度 > 30°/s */
41	
42	/* 模拟数据参数 */
43	
44	#define SIM_ACCEL_BASE      9.81f   /* 重力加速度 */
45	#define SIM_STEP_PERIOD     600     /* 模拟步行周期 (ms) */
46	
47	/****************************************************************************
48	 * Private Data
49	 ****************************************************************************/
50	
51	static sensor_data_t g_sensor;
52	static bool g_connected = false;
53	static bool g_initialized = false;
54	
55	/* 跌倒检测状态 */
56	
57	static uint64_t g_freefall_start = 0;
58	static uint64_t g_last_fall_time = 0;
59	
60	/* 步数检测状态 */
61	
62	static float g_step_last_peak = 0;
63	static float g_step_last_valley = 0;
64	static bool g_step_in_peak = false;
65	static uint64_t g_step_last_time = 0;
66	
67	/* 姿态历史 (用于平滑) */
68	
69	static posture_type_t g_posture_history[4] =
70	{
71	  POSTURE_STANDING,
72	  POSTURE_STANDING,
73	  POSTURE_STANDING,
74	  POSTURE_STANDING
75	};
76	static int g_posture_idx = 0;
77	
78	/* 模拟数据状态 */
79	
80	static uint64_t g_sim_start = 0;
81	static int32_t g_sim_steps = 0;
82	
83	/****************************************************************************
84	 * Private Functions
85	 ****************************************************************************/
86	
87	/**
88	 * 获取当前时间戳 (ms)
89	 */
90	
91	static uint64_t get_time_ms(void)
92	{
93	  struct timespec ts;
94	  clock_gettime(CLOCK_MONOTONIC, &ts);
95	  return (uint64_t)ts.tv_sec * 1000 + (uint64_t)ts.tv_nsec / 1000000;
96	}
97	
98	/**
99	 * 计算加速度合值
100	 */
101	
102	static float calc_accel_magnitude(float ax, float ay, float az)
103	{
104	  return sqrtf(ax * ax + ay * ay + az * az);
105	}
106	
107	/**
108	 * 计算角速度合值
109	 */
110	
111	static float calc_gyro_magnitude(float gx, float gy, float gz)
112	{
113	  return sqrtf(gx * gx + gy * gy + gz * gz);
114	}
115	
116	/**
117	 * 跌倒检测算法
118	 *
119	 * 检测模式: 自由落体 → 撞击
120	 *   1. 合加速度突然降到 < 3 m/s² (自由落体)
121	 *   2. 在 1.5s 内合加速度突然升到 > 25 m/s² (撞击)
122	 *   3. 确认跌倒
123	 */
124	
125	static void detect_fall(sensor_data_t *data)
126	{
127	  uint64_t now = get_time_ms();
128	  float mag = data->accel_magnitude;
129	
130	  /* 冷却期内不检测 */
131	
132	  if (now - g_last_fall_time < FALL_COOLDOWN_MS)
133	    {
134	      data->fall_state = FALL_STATE_RECOVERING;
135	      data->fall_detected = false;
136	      return;
137	    }
138	
139	  switch (data->fall_state)
140	    {
141	      case FALL_STATE_NORMAL:
142	        /* 检测自由落体 */
143	        if (mag < FREEFALL_THRESH)
144	          {
145	            data->fall_state = FALL_STATE_FREEFALL;
146	            g_freefall_start = now;
147	          }
148	        break;
149	
150	      case FALL_STATE_FREEFALL:
151	        /* 检测撞击 (必须在时间窗口内) */
152	        if (mag > IMPACT_THRESH &&
153	            (now - g_freefall_start) < FALL_TIME_WINDOW_MS)
154	          {
155	            data->fall_state = FALL_STATE_CONFIRMED;
156	            data->fall_detected = true;
157	            data->fall_time = now;
158	            g_last_fall_time = now;
159	          }
160	        else if ((now - g_freefall_start) >= FALL_TIME_WINDOW_MS)
161	          {
162	            /* 超时，恢复正常 */
163	            data->fall_state = FALL_STATE_NORMAL;
164	          }
165	        else if (mag >= FREEFALL_THRESH && mag <= IMPACT_THRESH)
166	          {
167	            /* 过渡阶段，继续等待 */
168	          }
169	        else
170	          {
171	            /* 加速度恢复正常，非跌倒 */
172	            data->fall_state = FALL_STATE_NORMAL;
173	          }
174	        break;
175	
176	      case FALL_STATE_CONFIRMED:
177	      case FALL_STATE_RECOVERING:
178	        /* 等待冷却 */
179	        if (now - g_last_fall_time >= FALL_COOLDOWN_MS)
180	          {
181	            data->fall_state = FALL_STATE_NORMAL;
182	            data->fall_detected = false;
183	          }
184	        break;
185	    }
186	}
187	
188	/**
189	 * 步数检测算法
190	 *
191	 * 基于加速度信号的峰值检测：
192	 *   1. 计算合加速度去除重力后的变化量
193	 *   2. 检测周期性峰值（步行特征）
194	 *   3. 两次峰值间隔在合理范围内则计一步
195	 */
196	
197	static void detect_steps(sensor_data_t *data)
198	{
199	  uint64_t now = get_time_ms();
200	  float mag = data->accel_magnitude;
201	
202	  /* 去除重力后的加速度变化 */
203	
204	  float delta = fabsf(mag - SIM_ACCEL_BASE);
205	
206	  if (delta > STEP_ACCEL_THRESH && !g_step_in_peak)
207	    {
208	      /* 进入峰值 */
209	
210	      g_step_in_peak = true;
211	      g_step_last_peak = mag;
212	    }
213	  else if (delta < STEP_ACCEL_THRESH * 0.5f && g_step_in_peak)
214	    {
215	      /* 离开峰值，计一步 */
216	
217	      g_step_in_peak = false;
218	
219	      uint64_t interval = now - g_step_last_time;
220	      if (interval >= STEP_MIN_INTERVAL &&
221	          interval <= STEP_MAX_INTERVAL)
222	        {
223	          data->step_count++;
224	        }
225	
226	      g_step_last_time = now;
227	    }
228	}
229	
230	/**
231	 * 姿态识别算法
232	 *
233	 * 基于重力方向判断姿态：
234	 *   - 站立: Z 轴朝上 (Z ≈ 9.8)
235	 *   - 坐姿: Z 轴倾斜 (Z ≈ 5-8)
236	 *   - 平躺: Z 轴水平 (Z ≈ 0, Y ≈ 9.8)
237	 *   - 侧躺: X 轴朝上 (X ≈ 9.8)
238	 *   - 行走: 周期性加速度变化 + 角速度
239	 */
240	
241	static void detect_posture(sensor_data_t *data)
242	{
243	  float ax = data->raw.accel_x;
244	  float ay = data->raw.accel_y;
245	  float az = data->raw.accel_z;
246	  float gyro_mag = data->gyro_magnitude;
247	
248	  posture_type_t posture = POSTURE_UNKNOWN;
249	
250	  /* 行走检测优先 (有节奏的加速度变化) */
251	
252	  if (gyro_mag > WALKING_GYRO_THRESH &&
253	      data->accel_magnitude > 8.0f &&
254	      data->accel_magnitude < 12.0f)
255	    {
256	      posture = POSTURE_WALKING;
257	    }
258	  /* 站立: Z 轴接近重力方向 */
259	
260	  else if (az > STANDING_Z_THRESH && fabsf(ax) < 4.0f)
261	    {
262	      posture = POSTURE_STANDING;
263	    }
264	  /* 坐姿: Z 轴倾斜 */
265	
266	  else if (az > 4.0f && az <= STANDING_Z_THRESH)
267	    {
268	      posture = POSTURE_SITTING;
269	    }
270	  /* 平躺: Z 轴接近水平，Y 轴朝上 */
271	
272	  else if (az < LYING_Z_THRESH && fabsf(ay) > 6.0f)
273	    {
274	      posture = POSTURE_LYING_FLAT;
275	    }
276	  /* 侧躺: X 轴朝上 */
277	
278	  else if (fabsf(ax) > 6.0f && az < LYING_Z_THRESH)
279	    {
280	      posture = POSTURE_LYING_SIDE;
281	    }
282	  else
283	    {
284	      posture = POSTURE_SITTING; /* 默认坐姿 */
285	    }
286	
287	  /* 姿态历史平滑 (取最近 4 次中最多的) */
288	
289	  g_posture_history[g_posture_idx] = posture;
290	  g_posture_idx = (g_posture_idx + 1) % 4;
291	
292	  /* 投票法取最常见姿态 */
293	
294	  int counts[POSTURE_COUNT] = {0};
295	  int max_count = 0;
296	  posture_type_t max_posture = posture;
297	  for (int i = 0; i < 4; i++)
298	    {
299	      int p = g_posture_history[i];
300	      counts[p]++;
301	      if (counts[p] > max_count)
302	        {
303	          max_count = counts[p];
304	          max_posture = (posture_type_t)p;
305	        }
306	    }
307	
308	  data->posture = max_posture;
309	  data->posture_name = sensor_get_posture_name(max_posture);
310	}
311	
312	/**
313	 * 活动强度计算
314	 */
315	
316	static void calc_activity_level(sensor_data_t *data)
317	{
318	  /* 基于加速度变化和角速度估算活动强度 (0-100) */
319	
320	  float accel_var = fabsf(data->accel_magnitude - SIM_ACCEL_BASE);
321	  float gyro_var = data->gyro_magnitude;
322	
323	  float level = (accel_var * 3.0f + gyro_var * 0.2f);
324	  if (level > 100.0f) level = 100.0f;
325	  if (level < 0.0f) level = 0.0f;
326	
327	  data->activity_level = (int32_t)level;
328	}
329	
330	/**
331	 * 生成模拟传感器数据
332	 * 当 BMI270 未连接时使用，模拟日常活动
333	 */
334	
335	static void generate_simulated_data(sensor_raw_t *raw)
336	{
337	  uint64_t now = get_time_ms();
338	  if (g_sim_start == 0) g_sim_start = now;
339	
340	  uint64_t elapsed = now - g_sim_start;
341	  float t = (float)elapsed / 1000.0f;  /* 秒 */
342	
343	  /* 模拟不同活动阶段 */
344	
345	  int phase = (elapsed / 30000) % 5;  /* 每 30 秒切换 */
346	
347	  float base_ax = 0.0f;
348	  float base_ay = 0.0f;
349	  float base_az = SIM_ACCEL_BASE;
350	  float noise_amp = 0.3f;
351	  float walk_freq = 2.0f;  /* 步行频率 2Hz */
352	
353	  switch (phase)
354	    {
355	      case 0: /* 站立静止 */
356	        base_ax = 0.2f;
357	        base_ay = 0.1f;
358	        base_az = 9.6f;
359	        noise_amp = 0.2f;
360	        break;
361	
362	      case 1: /* 行走 */
363	        base_ax = sinf(t * walk_freq * 2.0f * M_PI) * 2.0f;
364	        base_ay = cosf(t * walk_freq * 2.0f * M_PI) * 1.0f;
365	        base_az = 9.8f + sinf(t * walk_freq * 4.0f * M_PI) * 1.5f;
366	        noise_amp = 0.5f;
367	        g_sim_steps++;
368	        break;
369	
370	      case 2: /* 坐下 */
371	        base_ax = 0.1f;
372	        base_ay = 0.3f;
373	        base_az = 7.5f;
374	        noise_amp = 0.15f;
375	        break;
376	
377	      case 3: /* 行走 */
378	        base_ax = sinf(t * walk_freq * 2.0f * M_PI) * 2.5f;
379	        base_ay = cosf(t * walk_freq * 2.0f * M_PI) * 1.2f;
380	        base_az = 9.8f + sinf(t * walk_freq * 4.0f * M_PI) * 1.8f;
381	        noise_amp = 0.6f;
382	        g_sim_steps++;
383	        break;
384	
385	      case 4: /* 平躺休息 (偶尔触发跌倒模拟) */
386	        if (elapsed % 30000 > 28000)
387	          {
388	            /* 模拟跌倒: 自由落体→撞击 */
389	            base_ax = 0.5f;
390	            base_ay = 0.3f;
391	            base_az = 1.0f;  /* 低加速度 = 自由落体 */
392	            noise_amp = 0.2f;
393	          }
394	        else if (elapsed % 30000 > 28500)
395	          {
396	            /* 撞击 */
397	            base_ax = 5.0f;
398	            base_ay = 3.0f;
399	            base_az = 28.0f;
400	            noise_amp = 1.0f;
401	          }
402	        else
403	          {
404	            base_ax = 0.1f;
405	            base_ay = 9.5f;
406	            base_az = 0.3f;
407	            noise_amp = 0.1f;
408	          }
409	        break;
410	    }
411	
412	  /* 添加噪声 */
413	
414	  float noise_x = ((float)(rand() % 1000) / 500.0f - 1.0f) * noise_amp;
415	  float noise_y = ((float)(rand() % 1000) / 500.0f - 1.0f) * noise_amp;
416	  float noise_z = ((float)(rand() % 1000) / 500.0f - 1.0f) * noise_amp;
417	
418	  raw->accel_x = base_ax + noise_x;
419	  raw->accel_y = base_ay + noise_y;
420	  raw->accel_z = base_az + noise_z;
421	
422	  /* 陀螺仪: 行走时有角速度，静止时接近 0 */
423	
424	  float gyro_base = (phase == 1 || phase == 3) ? 40.0f : 2.0f;
425	  raw->gyro_x = ((float)(rand() % 1000) / 500.0f - 1.0f) * gyro_base;
426	  raw->gyro_y = ((float)(rand() % 1000) / 500.0f - 1.0f) * gyro_base;
427	  raw->gyro_z = ((float)(rand() % 1000) / 500.0f - 1.0f) * gyro_base;
428	
429	  raw->temperature = 29.0f + ((float)(rand() % 100) / 500.0f);
430	  raw->timestamp = now;
431	}
432	
433	/****************************************************************************
434	 * Public Functions
435	 ****************************************************************************/
436	
437	void sensor_manager_init(void)
438	{
439	  memset(&g_sensor, 0, sizeof(g_sensor));
440	  g_sensor.posture = POSTURE_STANDING;
441	  g_sensor.posture_name = "Standing";
442	  g_initialized = true;
443	  g_connected = false;
444	
445	  LV_LOG_USER("[SENSOR] Sensor manager initialized (simulated mode)");
446	}
447	
448	const sensor_data_t *sensor_manager_update(void)
449	{
450	  if (!g_initialized)
451	    {
452	      return &g_sensor;
453	    }
454	
455	  /* 读取传感器数据 (模拟) */
456	
457	  sensor_raw_t raw;
458	  generate_simulated_data(&raw);
459	
460	  g_sensor.raw = raw;
461	
462	  /* 计算合值 */
463	
464	  g_sensor.accel_magnitude = calc_accel_magnitude(
465	      raw.accel_x, raw.accel_y, raw.accel_z);
466	  g_sensor.gyro_magnitude = calc_gyro_magnitude(
467	      raw.gyro_x, raw.gyro_y, raw.gyro_z);
468	
469	  /* 跌倒检测 */
470	
471	  detect_fall(&g_sensor);
472	
473	  /* 步数检测 */
474	
475	  detect_steps(&g_sensor);
476	
477	  /* 姿态识别 */
478	
479	  detect_posture(&g_sensor);
480	
481	  /* 活动强度 */
482	
483	  calc_activity_level(&g_sensor);
484	
485	  /* 粗略卡路里估算 (kcal/min → kcal) */
486	  /* 活动强度每 100 对应约 8 kcal/min */
487	
488	  g_sensor.calories += (float)g_sensor.activity_level * 0.008f / 60.0f;
489	
490	  return &g_sensor;
491	}
492	
493	const sensor_data_t *sensor_manager_get(void)
494	{
495	  return &g_sensor;
496	}
497	
498	void sensor_manager_reset_steps(void)
499	{
500	  g_sensor.step_count = 0;
501	  g_sim_steps = 0;
502	}
503	
504	void sensor_manager_clear_fall(void)
505	{
506	  g_sensor.fall_detected = false;
507	  g_sensor.fall_state = FALL_STATE_NORMAL;
508	  g_last_fall_time = 0;
509	}
510	
511	const char *sensor_get_posture_name(posture_type_t posture)
512	{
513	  switch (posture)
514	    {
515	      case POSTURE_STANDING:  return "Standing";
