/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <nuttx/sensors/ioctl.h>

#ifdef CONFIG_MPU60X0_I2C
#  include <nuttx/i2c/i2c_master.h>
#  include <nuttx/sensors/mpu60x0.h>
#endif

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

#define MPU6500_DEV_PATH  "/dev/accel0"
#define MPU6500_I2C_PORT  0
#define MPU6500_I2C_ADDR  0x68

/****************************************************************************
 * External Functions
 ****************************************************************************/

/* BES vendor I2C initialization function (in libbeschip_ap.a) */

#ifdef CONFIG_MPU60X0_I2C
extern struct i2c_master_s *bes_i2cbus_initialize(int port);
#endif

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: init_mpu6500
 *
 * Description:
 *   Initialize MPU6500 IMU on I2C0 and register as /dev/accel0.
 *   Uses BES vendor I2C driver + NuttX mpu60x0 sensor driver.
 *
 ****************************************************************************/

#ifdef CONFIG_MPU60X0_I2C
static int init_mpu6500(void)
{
  struct i2c_master_s *i2c;
  struct mpu_config_s config;
  int ret;

  printf("[SENSOR] Initializing MPU6500 on I2C%d (addr 0x%02X)...\n",
         MPU6500_I2C_PORT, MPU6500_I2C_ADDR);

  /* Check if device already exists */

  if (access(MPU6500_DEV_PATH, F_OK) == 0)
    {
      printf("[SENSOR] %s already exists, skipping init\n",
             MPU6500_DEV_PATH);
      return 0;
    }

  /* Get I2C bus handle from BES vendor driver */

  i2c = bes_i2cbus_initialize(MPU6500_I2C_PORT);
  if (i2c == NULL)
    {
      printf("[SENSOR] ERROR: Failed to initialize I2C%d\n",
             MPU6500_I2C_PORT);
      return -ENODEV;
    }

  printf("[SENSOR] I2C%d initialized successfully\n", MPU6500_I2C_PORT);

  /* Configure MPU6500 */

  memset(&config, 0, sizeof(config));
  config.i2c  = i2c;
  config.addr = MPU6500_I2C_ADDR;

  /* Register MPU6500 as /dev/accel0 */

  ret = mpu60x0_register(MPU6500_DEV_PATH, &config);
  if (ret < 0)
    {
      printf("[SENSOR] ERROR: Failed to register MPU6500: %d\n", ret);
      return ret;
    }

  printf("[SENSOR] MPU6500 registered as %s\n", MPU6500_DEV_PATH);
  return 0;
}
#endif /* CONFIG_MPU60X0_I2C */

/****************************************************************************
 * Name: test_mpu6500
 *
 * Description:
 *   Test MPU6500 IMU sensor by reading accelerometer and gyroscope data.
 *
 ****************************************************************************/

#ifdef CONFIG_MPU60X0_I2C
static int test_mpu6500(void)
{
  int fd;
  int ret;
  float accel[3];
  float gyro[3];

  printf("\n=== MPU6500 IMU Test ===\n");

  /* Open the MPU6500 device */

  fd = open(MPU6500_DEV_PATH, O_RDONLY);
  if (fd < 0)
    {
      printf("ERROR: Failed to open %s: %d\n", MPU6500_DEV_PATH, errno);
      return -errno;
    }

  printf("SUCCESS: Opened %s\n", MPU6500_DEV_PATH);

  /* Read accelerometer data */

  ret = ioctl(fd, SNIOC_READ_ACCEL, (unsigned long)accel);
  if (ret < 0)
    {
      printf("WARNING: Failed to read accelerometer: %d\n", errno);
    }
  else
    {
      printf("Accelerometer (m/s²):\n");
      printf("  X: %8.2f\n", accel[0]);
      printf("  Y: %8.2f\n", accel[1]);
      printf("  Z: %8.2f\n", accel[2]);
    }

  /* Read gyroscope data */

  ret = ioctl(fd, SNIOC_READ_GYRO, (unsigned long)gyro);
  if (ret < 0)
    {
      printf("WARNING: Failed to read gyroscope: %d\n", errno);
    }
  else
    {
      printf("Gyroscope (°/s):\n");
      printf("  X: %8.2f\n", gyro[0]);
      printf("  Y: %8.2f\n", gyro[1]);
      printf("  Z: %8.2f\n", gyro[2]);
    }

  /* Close the device */

  close(fd);
  printf("MPU6500 test completed.\n");

  return OK;
}
#endif /* CONFIG_MPU60X0_I2C */

/****************************************************************************
 * Name: test_w25q64
 *
 * Description:
 *   Test W25Q64 SPI Flash by checking device node.
 *
 ****************************************************************************/

#ifdef CONFIG_MTD_W25Q
static int test_w25q64(void)
{
  printf("\n=== W25Q64 SPI Flash Test ===\n");

  /* Check if SPI device exists */

  if (access("/dev/spi0", F_OK) == 0)
    {
      printf("SUCCESS: /dev/spi0 exists\n");
    }
  else
    {
      printf("ERROR: /dev/spi0 not found\n");
    }

  /* Check if MTD device exists */

  if (access("/dev/mtdblock1", F_OK) == 0)
    {
      printf("SUCCESS: /dev/mtdblock1 exists\n");
    }
  else
    {
      printf("INFO: /dev/mtdblock1 not found\n");
      printf("      W25Q64 MTD driver not registered yet\n");
    }

  printf("W25Q64 test completed.\n");

  return OK;
}
#endif /* CONFIG_MTD_W25Q */

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: sensor_test_main
 *
 * Description:
 *   Main entry point for the sensor test application.
 *
 ****************************************************************************/

int main(int argc, char *argv[])
{
  printf("=== BES2800BP Sensor Test ===\n");

#ifdef CONFIG_MPU60X0_I2C
  /* Initialize MPU6500 driver first */

  init_mpu6500();

  /* Then test it */

  test_mpu6500();
#else
  printf("\nMPU6500: Not enabled (CONFIG_MPU60X0_I2C=n)\n");
  printf("  Enable in defconfig: CONFIG_MPU60X0_I2C=y\n");
  printf("  Also need: CONFIG_SENSORS=y, CONFIG_MPU60X0=y\n");
#endif

#ifdef CONFIG_MTD_W25Q
  test_w25q64();
#else
  printf("\nW25Q64: Not enabled (CONFIG_MTD_W25Q=n)\n");
#endif

  printf("\n=== Test Complete ===\n");

  return OK;
}

