 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>

#ifdef CONFIG_SENSORS_MPU60X0
#  include <nuttx/i2c/i2c_master.h>
#  include <nuttx/sensors/mpu60x0.h>
#endif

#ifdef CONFIG_MTD_W25
#  include <nuttx/spi/spi.h>
#  include <nuttx/mtd/mtd.h>
#  include <nuttx/fs/fs.h>
#endif

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* MPU6500 config */

#define MPU6500_DEV_PATH  "/dev/accel0"
#define MPU6500_I2C_PORT  0
#define MPU6500_I2C_ADDR  0x68

/* W25Q64 config */

#define W25Q64_SPI_PORT   0
#define W25Q64_MOUNTPOINT "/mnt/w25q64"

/* MPU60x0 raw data structure (matches driver) */

struct mpu_raw_data_s
{
  int16_t x_accel;
  int16_t y_accel;
  int16_t z_accel;
  int16_t temp;
  int16_t x_gyro;
  int16_t y_gyro;
  int16_t z_gyro;
};

/****************************************************************************
 * External Functions (BES vendor library: libbeschip_ap.a)
 ****************************************************************************/

#ifdef CONFIG_SENSORS_MPU60X0
extern struct i2c_master_s *bes_i2cbus_initialize(int port);
#endif

#ifdef CONFIG_MTD_W25
extern struct spi_dev_s *bes_spibus_initialize(int port);
#endif

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: init_mpu6500
 *
 * Description:
 *   Initialize MPU6500 IMU on I2C0 and register as /dev/accel0.
 *
 ****************************************************************************/

#ifdef CONFIG_SENSORS_MPU60X0
static int init_mpu6500(void)
{
  struct i2c_master_s *i2c;
  struct mpu_config_s config;
  int ret;

  printf("[MPU6500] Initializing on I2C%d (addr 0x%02X)...\n",
         MPU6500_I2C_PORT, MPU6500_I2C_ADDR);

  /* Check if device already exists */

  if (access(MPU6500_DEV_PATH, F_OK) == 0)
    {
      printf("[MPU6500] %s already exists, skipping init\n",
             MPU6500_DEV_PATH);
      return 0;
    }

  /* Get I2C bus handle from BES vendor driver */

  i2c = bes_i2cbus_initialize(MPU6500_I2C_PORT);
  if (i2c == NULL)
    {
      printf("[MPU6500] ERROR: Failed to initialize I2C%d\n",
             MPU6500_I2C_PORT);
      return -ENODEV;
    }

  printf("[MPU6500] I2C%d initialized\n", MPU6500_I2C_PORT);

  /* Configure MPU6500 */

  memset(&config, 0, sizeof(config));
  config.i2c  = i2c;
  config.addr = MPU6500_I2C_ADDR;

  /* Register MPU6500 as /dev/accel0 */

  ret = mpu60x0_register(MPU6500_DEV_PATH, &config);
  if (ret < 0)
    {
      printf("[MPU6500] ERROR: Failed to register: %d\n", ret);
      return ret;
    }

  printf("[MPU6500] Registered as %s\n", MPU6500_DEV_PATH);
  return 0;
}

static int test_mpu6500(void)
{
  int fd;
  ssize_t nbytes;
  struct mpu_raw_data_s data;
  float accel_scale = 16384.0f;  /* ±2g range: 16384 LSB/g */
  float gyro_scale = 131.0f;     /* ±250°/s range: 131 LSB/°/s */

  printf("\n=== MPU6500 IMU Test ===\n");

  fd = open(MPU6500_DEV_PATH, O_RDONLY);
  if (fd < 0)
    {
      printf("ERROR: Failed to open %s: %d\n", MPU6500_DEV_PATH, errno);
      return -errno;
    }

  printf("SUCCESS: Opened %s\n", MPU6500_DEV_PATH);

  /* Read raw sensor data */

  nbytes = read(fd, &data, sizeof(data));
  if (nbytes < sizeof(data))
    {
      printf("ERROR: Failed to read sensor data: %d\n", errno);
      close(fd);
      return -errno;
    }

  /* Convert to physical units */

  printf("Raw data:\n");
  printf("  Accel: X=%6d Y=%6d Z=%6d\n",
         data.x_accel, data.y_accel, data.z_accel);
  printf("  Gyro:  X=%6d Y=%6d Z=%6d\n",
         data.x_gyro, data.y_gyro, data.z_gyro);
  printf("  Temp:  %6d\n", data.temp);

  printf("\nConverted:\n");
  printf("  Accelerometer (g):   X=%8.3f Y=%8.3f Z=%8.3f\n",
         (float)data.x_accel / accel_scale,
         (float)data.y_accel / accel_scale,
         (float)data.z_accel / accel_scale);
  printf("  Gyroscope (°/s):     X=%8.3f Y=%8.3f Z=%8.3f\n",
         (float)data.x_gyro / gyro_scale,
         (float)data.y_gyro / gyro_scale,
         (float)data.z_gyro / gyro_scale);
  printf("  Temperature (°C):    %8.2f\n",
         (float)data.temp / 340.0f + 36.53f);

  close(fd);
  printf("MPU6500 test completed.\n");
  return OK;
}
#endif /* CONFIG_SENSORS_MPU60X0 */

/****************************************************************************
 * Name: init_w25q64
 *
 * Description:
 *   Initialize W25Q64 SPI Flash and mount FAT filesystem.
 *
 ****************************************************************************/

#ifdef CONFIG_MTD_W25
static int init_w25q64(void)
{
  struct spi_dev_s *spi;
  struct mtd_dev_s *mtd;
  int ret;

  printf("[W25Q64] Initializing on SPI%d...\n", W25Q64_SPI_PORT);

  /* Check if already mounted */

  if (access(W25Q64_MOUNTPOINT, F_OK) == 0)
    {
      printf("[W25Q64] %s already exists, skipping init\n",
             W25Q64_MOUNTPOINT);
      return 0;
    }

  /* Get SPI bus handle from BES vendor driver */

  spi = bes_spibus_initialize(W25Q64_SPI_PORT);
  if (spi == NULL)
    {
      printf("[W25Q64] ERROR: Failed to initialize SPI%d\n",
             W25Q64_SPI_PORT);
      return -ENODEV;
    }

  printf("[W25Q64] SPI%d initialized\n", W25Q64_SPI_PORT);

  /* Bind SPI to W25 flash driver */

  mtd = w25_initialize(spi);
  if (mtd == NULL)
    {
      printf("[W25Q64] ERROR: Failed to bind W25 driver\n");
      return -ENODEV;
    }

  /* Register as block device (minor=1 to avoid conflict) */

  ret = ftl_initialize(1, mtd);
  if (ret < 0)
    {
      printf("[W25Q64] ERROR: FTL init failed: %d\n", ret);
      return ret;
    }

  printf("[W25Q64] Registered as /dev/mtdblock1\n");

  /* Mount FAT filesystem */

  ret = nx_mount("/dev/mtdblock1", W25Q64_MOUNTPOINT, "vfat", 0, NULL);
  if (ret < 0)
    {
      printf("[W25Q64] WARNING: Mount failed: %d\n", ret);
      printf("  Format first: mkfatfs /dev/mtdblock1\n");
    }
  else
    {
      printf("[W25Q64] Mounted at %s\n", W25Q64_MOUNTPOINT);
    }

  return 0;
}

static int test_w25q64(void)
{
  printf("\n=== W25Q64 SPI Flash Test ===\n");

  if (access("/dev/spi0", F_OK) == 0)
    {
      printf("SPI bus:  /dev/spi0 exists\n");
    }

  if (access("/dev/mtdblock1", F_OK) == 0)
    {
      printf("MTD dev:  /dev/mtdblock1 exists\n");
    }
  else
    {
      printf("MTD dev:  /dev/mtdblock1 not found\n");
    }

  if (access(W25Q64_MOUNTPOINT, F_OK) == 0)
    {
      printf("Mount:    %s mounted\n", W25Q64_MOUNTPOINT);
    }
  else
    {
      printf("Mount:    %s not mounted\n", W25Q64_MOUNTPOINT);
    }

  printf("W25Q64 test completed.\n");
  return OK;
}
#endif /* CONFIG_MTD_W25 */

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int main(int argc, char *argv[])
{
  printf("=== BES2800BP Sensor Test ===\n");

#ifdef CONFIG_SENSORS_MPU60X0
  init_mpu6500();
  test_mpu6500();
#else
  printf("\nMPU6500: Not enabled\n");
  printf("  Add to defconfig:\n");
  printf("    CONFIG_SENSORS=y\n");
  printf("    CONFIG_SENSORS_MPU60X0=y\n");
  printf("    CONFIG_MPU60X0_I2C=y\n");
#endif

#ifdef CONFIG_MTD_W25
  init_w25q64();
  test_w25q64();
#else
  printf("\nW25Q64: Not enabled\n");
  printf("  Add to defconfig:\n");
  printf("    CONFIG_SPI=y\n");
  printf("    CONFIG_MTD_W25=y\n");
#endif

  printf("\n=== Test Complete ===\n");
  return OK;
}

