  /* Main event loop */

  while (1)
    {
      uint32_t idle;

      /* 更新传感器数据并同步到 UI */

      data_collector_update();

      idle = lv_timer_handler();
      idle = idle ? idle : 1;
      usleep(idle * 1000);
    }

  lv_nuttx_deinit(&result);
  lv_deinit();
  return 0;
}

